import { createClient } from "npm:@supabase/supabase-js@2.57.2";

const corsHeaders = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type" };

const DRAFTS_B64 = "";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  try {
    const url = new URL(req.url);
    const token = url.searchParams.get("token");
    if (token !== "publish-1778792982709") return new Response("forbidden", { status: 403, headers: corsHeaders });

    const supabase = createClient(Deno.env.get("SUPABASE_URL"), Deno.env.get("SUPABASE_SERVICE_ROLE_KEY"));
    const drafts = JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(DRAFTS_B64), c => c.charCodeAt(0))));
    const results = [];
    for (const [chapter_id, draft_md] of Object.entries(drafts)) {
      const { error: u1 } = await supabase.from("book_chapters").update({ published_excerpt: draft_md, status: "published", published_at: new Date().toISOString() }).eq("id", chapter_id);
      if (u1) { results.push({ chapter_id, error: u1.message }); continue; }
      await supabase.from("book_chapter_drafts").update({ is_current: false }).eq("chapter_id", chapter_id);
      const { error: u2 } = await supabase.from("book_chapter_drafts").insert({ chapter_id, model: "google/gemini-2.5-pro", prompt_snapshot: "auto-synthesis from PRD v1.0", draft_md, is_current: true });
      results.push({ chapter_id, ok: !u2, err: u2?.message });
    }
    return new Response(JSON.stringify({ ok: true, results }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } });
  }
});
